/**
 * Build script for Render Static Site deployment.
 * Injects the deployed backend Web Service URL from environment variables into config.js.
 */
const fs = require('fs');
const path = require('path');

const targetFile = path.join(__dirname, 'config.js');
const backendUrl = process.env.BACKEND_URL || process.env.HEALTHBRIDGE_API_URL || 'https://healthbridge-ai.onrender.com';

const sanitizedUrl = backendUrl.replace(/\/+$/, '');

const content = `/**
 * HealthBridge AI - Runtime Frontend Configuration
 * Auto-generated by build-config.js during Render Static Site build.
 */
window.HEALTHBRIDGE_API_URL = "${sanitizedUrl}";
console.log("[HealthBridge AI] Configured Backend URL:", window.HEALTHBRIDGE_API_URL);
`;

try {
  fs.writeFileSync(targetFile, content, 'utf8');
  console.log('[build-config.js] Successfully generated config.js:');
  console.log('  Target file:', targetFile);
  console.log('  BACKEND_URL:', sanitizedUrl);
} catch (err) {
  console.error('[build-config.js] Failed to write config.js:', err);
  process.exit(1);
}
